// Generated from the backend database design (prisma/schema.prisma). Do not edit by hand: rebuild it.
export default "<section class=\"block \" id=\"value-lists\">\n      <h2>Value lists</h2>\n      <p>Columns that only accept a fixed set of values (PostgreSQL enums). Use them exactly as written, in capitals, e.g. <code>WHERE status = 'COMPLETED'</code>.</p>\n      <div class=\"enums\"><div class=\"enumcard\" id=\"e-role\"><h3><code>Role</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-users\"><code>users.role</code></a></p>\n  <ul><li><code>SUPER_ADMIN</code> <span>all stores, all settings</span></li><li><code>STORE_MANAGER</code> <span>manages assigned stores</span></li><li><code>CASHIER</code> <span>sells in assigned stores</span></li></ul></div><div class=\"enumcard\" id=\"e-stockmovementtype\"><h3><code>StockMovementType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-stock-movements\"><code>stock_movements.type</code></a></p>\n  <ul><li><code>PURCHASE</code> <span>goods received from supplier</span></li><li><code>SALE</code></li><li><code>REFUND</code> <span>goods returned by customer</span></li><li><code>ADJUSTMENT</code> <span>manual count correction, damage, loss</span></li><li><code>TRANSFER_OUT</code></li><li><code>TRANSFER_IN</code></li><li><code>RECIPE</code> <span>ingredients used up by drinks / dishes sold</span></li><li><code>PRODUCTION</code> <span>finished pieces made here (bakery batch)</span></li><li><code>PRODUCTION_USE</code> <span>ingredients used to make a batch</span></li><li><code>WASTE</code> <span>written off: expired, unsold, damaged</span></li></ul></div><div class=\"enumcard\" id=\"e-transferstatus\"><h3><code>TransferStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-stock-transfers\"><code>stock_transfers.status</code></a></p>\n  <ul><li><code>IN_TRANSIT</code></li><li><code>RECEIVED</code></li><li><code>CANCELLED</code></li></ul></div><div class=\"enumcard\" id=\"e-salestatus\"><h3><code>SaleStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-sales\"><code>sales.status</code></a></p>\n  <ul><li><code>COMPLETED</code></li><li><code>PARTIALLY_REFUNDED</code></li><li><code>REFUNDED</code></li><li><code>VOIDED</code></li></ul></div><div class=\"enumcard\" id=\"e-paymentmethod\"><h3><code>PaymentMethod</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-payments\"><code>payments.method</code></a>, <a href=\"#t-refunds\"><code>refunds.method</code></a>, <a href=\"#t-wallet-transactions\"><code>wallet_transactions.method</code></a>, <a href=\"#t-vouchers\"><code>vouchers.sold_method</code></a></p>\n  <ul><li><code>CASH</code></li><li><code>CARD</code></li><li><code>KHQR</code></li><li><code>BANK_TRANSFER</code></li><li><code>E_WALLET</code> <span>other e-wallets (Wing, TrueMoney...)</span></li><li><code>WALLET</code> <span>the store&#x27;s own wallet card (stored balance)</span></li><li><code>VOUCHER</code> <span>gift voucher code</span></li><li><code>OTHER</code></li></ul></div><div class=\"enumcard\" id=\"e-shiftstatus\"><h3><code>ShiftStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-shifts\"><code>shifts.status</code></a></p>\n  <ul><li><code>OPEN</code></li><li><code>CLOSED</code></li></ul></div><div class=\"enumcard\" id=\"e-loyaltytxtype\"><h3><code>LoyaltyTxType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-loyalty-transactions\"><code>loyalty_transactions.type</code></a></p>\n  <ul><li><code>EARN</code></li><li><code>REDEEM</code></li><li><code>REVERSE</code> <span>points taken back on refund</span></li><li><code>RETURN</code> <span>redeemed points given back on refund</span></li><li><code>ADJUST</code> <span>manual change by staff</span></li></ul></div><div class=\"enumcard\" id=\"e-webhookdeliverystatus\"><h3><code>WebhookDeliveryStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-webhook-deliveries\"><code>webhook_deliveries.status</code></a></p>\n  <ul><li><code>PENDING</code></li><li><code>SUCCESS</code></li><li><code>FAILED</code></li></ul></div><div class=\"enumcard\" id=\"e-purchaseorderstatus\"><h3><code>PurchaseOrderStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-purchase-orders\"><code>purchase_orders.status</code></a></p>\n  <ul><li><code>DRAFT</code></li><li><code>ORDERED</code></li><li><code>PARTIALLY_RECEIVED</code></li><li><code>RECEIVED</code></li><li><code>CANCELLED</code></li></ul></div><div class=\"enumcard\" id=\"e-promotiontype\"><h3><code>PromotionType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-promotions\"><code>promotions.type</code></a></p>\n  <ul><li><code>PERCENT_OFF</code> <span>value = percent, e.g. 10</span></li><li><code>AMOUNT_OFF</code> <span>value = amount off each unit</span></li><li><code>BUY_X_GET_Y</code> <span>buy `buyQty`, get `getQty` free (same product)</span></li></ul></div><div class=\"enumcard\" id=\"e-khqrstatus\"><h3><code>KhqrStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-khqr-payments\"><code>khqr_payments.status</code></a></p>\n  <ul><li><code>PENDING</code></li><li><code>PAID</code></li><li><code>EXPIRED</code></li></ul></div><div class=\"enumcard\" id=\"e-walletcardstatus\"><h3><code>WalletCardStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-wallet-cards\"><code>wallet_cards.status</code></a></p>\n  <ul><li><code>INACTIVE</code> <span>printed, not given to a customer yet</span></li><li><code>ACTIVE</code></li><li><code>BLOCKED</code> <span>lost / suspicious: cannot pay or top up</span></li><li><code>CLOSED</code> <span>replaced or cancelled; balance moved away</span></li></ul></div><div class=\"enumcard\" id=\"e-wallettxtype\"><h3><code>WalletTxType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-wallet-transactions\"><code>wallet_transactions.type</code></a></p>\n  <ul><li><code>TOPUP</code></li><li><code>PAYMENT</code></li><li><code>REFUND</code></li><li><code>ADJUST</code></li><li><code>TRANSFER_IN</code></li><li><code>TRANSFER_OUT</code></li></ul></div><div class=\"enumcard\" id=\"e-coupontype\"><h3><code>CouponType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-coupon-campaigns\"><code>coupon_campaigns.type</code></a></p>\n  <ul><li><code>PERCENT</code> <span>value = percent off the sale</span></li><li><code>AMOUNT</code> <span>value = amount off the sale</span></li></ul></div><div class=\"enumcard\" id=\"e-voucherstatus\"><h3><code>VoucherStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-vouchers\"><code>vouchers.status</code></a></p>\n  <ul><li><code>INACTIVE</code> <span>printed, not sold yet (sold vouchers only)</span></li><li><code>ACTIVE</code></li><li><code>USED</code> <span>value fully spent</span></li><li><code>VOID</code> <span>cancelled</span></li></ul></div><div class=\"enumcard\" id=\"e-ordertype\"><h3><code>OrderType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-sales\"><code>sales.order_type</code></a>, <a href=\"#t-online-orders\"><code>online_orders.order_type</code></a></p>\n  <ul><li><code>RETAIL</code> <span>normal shop sale</span></li><li><code>TAKEAWAY</code></li><li><code>DINE_IN</code></li><li><code>PICKUP</code> <span>ordered ahead online</span></li><li><code>DELIVERY</code></li></ul></div><div class=\"enumcard\" id=\"e-kitchenstatus\"><h3><code>KitchenStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-sales\"><code>sales.kitchen_status</code></a></p>\n  <ul><li><code>NONE</code> <span>not a kitchen order</span></li><li><code>NEW</code></li><li><code>PREPARING</code></li><li><code>READY</code></li><li><code>COMPLETED</code></li><li><code>CANCELLED</code></li></ul></div><div class=\"enumcard\" id=\"e-recipeeffecttype\"><h3><code>RecipeEffectType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-modifier-effects\"><code>modifier_effects.type</code></a></p>\n  <ul><li><code>SCALE</code> <span>percent change: all ingredients except pieces (cups, lids), or only `ingredientId`</span></li><li><code>REPLACE</code> <span>use `replaceWithId` instead of `ingredientId` (oat milk instead of fresh milk)</span></li><li><code>ADD</code> <span>add `quantity` of `ingredientId` (extra shot, whipped cream)</span></li></ul></div><div class=\"enumcard\" id=\"e-onlineorderstatus\"><h3><code>OnlineOrderStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-online-orders\"><code>online_orders.status</code></a></p>\n  <ul><li><code>PENDING_PAYMENT</code> <span>waiting for the KHQR payment</span></li><li><code>PAY_AT_COUNTER</code> <span>customer pays the cashier</span></li><li><code>PAID</code> <span>became a sale and went to the barista</span></li><li><code>CANCELLED</code></li><li><code>EXPIRED</code> <span>not paid in time</span></li><li><code>FAILED</code> <span>payment received but the sale could not be created (needs a manager)</span></li></ul></div><div class=\"enumcard\" id=\"e-productionstatus\"><h3><code>ProductionStatus</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-production-batches\"><code>production_batches.status</code></a></p>\n  <ul><li><code>PLANNED</code></li><li><code>DONE</code></li><li><code>CANCELLED</code></li></ul></div><div class=\"enumcard\" id=\"e-wastereason\"><h3><code>WasteReason</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-waste-entries\"><code>waste_entries.reason</code></a></p>\n  <ul><li><code>EXPIRED</code></li><li><code>UNSOLD</code></li><li><code>DAMAGED</code></li><li><code>QUALITY</code></li><li><code>OTHER</code></li></ul></div><div class=\"enumcard\" id=\"e-approvalaction\"><h3><code>ApprovalAction</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-approvals\"><code>approvals.action</code></a></p>\n  <ul><li><code>DISCOUNT</code></li><li><code>REFUND</code></li><li><code>VOID</code></li><li><code>CASH_OUT</code></li></ul></div><div class=\"enumcard\" id=\"e-cashmovetype\"><h3><code>CashMoveType</code></h3>\n  <p class=\"used\">Used by <a href=\"#t-cash-movements\"><code>cash_movements.type</code></a></p>\n  <ul><li><code>PAY_IN</code> <span>money put into the drawer (float, change from the bank)</span></li><li><code>PAY_OUT</code> <span>money taken out (supplier paid in cash, bank drop, petty cash)</span></li></ul></div></div>\n    </section>";
